KNIFE_LAT = 34.7272834777832
KNIFE_LON = -87.82411193847656
KNIFE_HGT = 151.7379913330078
KNIFE_LANDMASK = 1.0
KNIFE_J = 23
KNIFE_I = 135

N_LEVELS = 49

# --- import-time premise assertions ---------------------------------
_RD, _RV, _CP, _P0, _XLV = 287.0, 461.6, 1004.5, 1.0e5, 2.5e6
_SVP1, _SVP2, _SVP3, _SVPT0 = 0.6112, 17.67, 29.65, 273.15


def _sat(theta, qv, qc, p):
    """(qt >= qs member flag, theta_es) on the module's own constants."""
    t = theta * (p / _P0) ** (_RD / _CP)
    es = 1000.0 * _SVP1 * np.exp(_SVP2 * (t - _SVPT0) / (t - _SVP3))
    qs = (_RD / _RV) * es / (p - es)
    return (qv + qc) >= qs, theta * np.exp(_XLV * qs / (_CP * t))


def _lowest_run(flag, minlen=2):
    k = 0
    while k < len(flag):
        if flag[k]:
            j = k
            while j + 1 < len(flag) and flag[j + 1]:
                j += 1
            if j - k + 1 >= minlen:
                return k, j
            k = j
        k += 1
    return None


for _p, _pre in ((0, "WIN"), (1, "KNIFE")):
    _th = globals()[_pre + "_THETA"]
    _qv = globals()[_pre + "_QV"]
    _qc = globals()[_pre + "_QC"]
    _pp = globals()[_pre + "_P"]
    _e = globals()[_pre + "_E"]
    _memb, _thes = _sat(_th, _qv, _qc, _pp)
    _run = _lowest_run(_memb)
    assert _run is not None, (_pre, "must have a >=2-cell saturated run")
    _kb, _kt = _run
    assert _thes[_kt] < _thes[_kb], (_pre, "run must be moist-unstable")
    assert len(_th) == N_LEVELS

_memb_w, _thes_w = _sat(WIN_THETA, WIN_QV, WIN_QC, WIN_P)
_kb_w, _kt_w = _lowest_run(_memb_w)
assert (_kb_w, _kt_w) == (10, 17), (_kb_w, _kt_w)
# an interior theta_es maximum at k4, >= 2 cells below the base: the
# construction under which the two candidate ebar windows differ.
assert _thes_w[4] > _thes_w[3] and _thes_w[4] > _thes_w[5]
assert _kb_w - 4 >= 2
# ... and REAL non-uniform subgrid energy across that gap, which is
# what makes the two windows numerically different at all.
assert WIN_E[4:_kt_w + 2].max() / WIN_E[4:_kt_w + 2].min() > 1.0e4

_memb_k, _thes_k = _sat(KNIFE_THETA, KNIFE_QV, KNIFE_QC, KNIFE_P)
_kb_k, _kt_k = _lowest_run(_memb_k)
assert (_kb_k, _kt_k) == (13, 14), (_kb_k, _kt_k)
# the knife edge itself: theta[0] - 0.05 K manufactures an interior
# theta_es maximum at k1 that is NOT present in the unperturbed column.
assert not (_thes_k[1] > _thes_k[0] and _thes_k[1] > _thes_k[2])
_thp = KNIFE_THETA.copy()
_thp[0] -= 0.05
_, _thes_p = _sat(_thp, KNIFE_QV, KNIFE_QC, KNIFE_P)
assert _thes_p[1] > _thes_p[0] and _thes_p[1] > _thes_p[2], (
    "knife premise: -0.05 K at level 0 must create the k1 peak")
